import socket
print(socket.gethostname())
print(socket.gethostbyname(socket.gethostname()))
# Try to resolve the host
try:
    print(socket.getaddrinfo("host", 5432))
except Exception as e:
    print(f"host: {e}")
try:
    print(socket.getaddrinfo("localhost", 5432))
except Exception as e:
    print(f"localhost: {e}")
try:
    print(socket.getaddrinfo("127.0.0.1", 5432))
except Exception as e:
    print(f"127.0.0.1: {e}")

import subprocess

# Try different package names
for pkg in ["postgresql-16", "postgresql-15", "postgresql-14", "postgresql-server", "postgresql-client"]:
    r = subprocess.run(["apt-cache", "show", pkg], capture_output=True, text=True, timeout=10)
    if r.stdout:
        print(f"{pkg}: FOUND")
        # Show just version
        for line in r.stdout.split('\n'):
            if line.startswith("Version:"):
                print(f"  {line}")
    else:
        print(f"{pkg}: not found ({r.stderr[:100]})")

